(3248399, 454107, 70164, '<td valign="top">Grainy and boring.</td>', 'Grainy and boring.', '2007-01-17 18:14:33.000000', NULL, 1),
(3248406, 454201, 70164, '<td valign="top">Wow, thats really good.  Very clear.  I like it. 10</td>', 'Wow, thats really good.  Very clear.  I like it. 10', '2007-01-17 18:16:06.000000', NULL, 1),
(3248422, 454227, 45519, '<td valign="top">Creative</td>', 'Creative', '2007-01-17 18:18:10.000000', NULL, 1),
(3248423, 453996, 70164, '<td valign="top">I dont get the title..or should I say, the tittle.  I think it would have been neater if the matches werent tied up like that.</td>', 'I dont get the title..or should I say, the tittle.  I think it would have been neater if the matches werent tied up like that.', '2007-01-17 18:18:23.000000', NULL, 1),
