(3248434, 453959, 45519, '<td valign="top">Creative ... and nicely done.</td>', 'Creative ... and nicely done.', '2007-01-17 18:19:55.000000', NULL, 1),
(3248435, 453227, 70164, '<td valign="top">Good idea, someone else did the same thing and I like theirs better.  But yours is good too, it shows all details cleary except the matchhead on the right.  8</td>', 'Good idea, someone else did the same thing and I like theirs better.  But yours is good too, it shows all details cleary except the matchhead on the right.  8', '2007-01-17 18:19:55.000000', NULL, 1),
