(3248441, 453158, 29293, '<td valign="top">nice use of perspective</td>', 'nice use of perspective', '2007-01-17 18:21:10.000000', NULL, 1),
(3248442, 451098, 70164, '<td valign="top">Good idea but the lighting is a little dull on the bottom ring and the top ring looks a tad blurry.  7</td>', 'Good idea but the lighting is a little dull on the bottom ring and the top ring looks a tad blurry.  7', '2007-01-17 18:21:21.000000', NULL, 1),
(3248443, 452716, 45519, '<td valign="top">I love how the flame forms an almost devilish pitchfork effect.  Well executed idea. *8*</td>', 'I love how the flame forms an almost devilish pitchfork effect.  Well executed idea. *8*', '2007-01-17 18:21:23.000000', NULL, 1),
(3248445, 454333, 70164, '<td valign="top">Neat idea.  I like it. 8</td>', 'Neat idea.  I like it. 8', '2007-01-17 18:21:56.000000', NULL, 1),
(3248447, 453260, 70164, '<td valign="top">I would have liked to see colors.</td>', 'I would have liked to see colors.', '2007-01-17 18:22:20.000000', NULL, 1),
(3248448, 454225, 29293, '<td valign="top">i love the light behind his head</td>', 'i love the light behind his head', '2007-01-17 18:22:36.000000', NULL, 1),
(3248450, 451723, 70164, '<td valign="top">haha, I like how you didnt get any of the wood on the odd stick burnt.  Very clever.  9</td>', 'haha, I like how you didnt get any of the wood on the odd stick burnt.  Very clever.  9', '2007-01-17 18:23:12.000000', NULL, 1),
(3248451, 452610, 45519, '<td valign="top">Outstanding composition, quality of light and treatment!  *10*</td>', 'Outstanding composition, quality of light and treatment!  *10*', '2007-01-17 18:23:13.000000', NULL, 1),
(3248459, 453396, 45519, '<td valign="top">Solid concept, given the boys'' matching clothing and positions.  Unfortunately the DOF is too shallow to make it work; even a stop or two more detail in the foreground child would really make this one stand out. *6*</td>', 'Solid concept, given the boys'' matching clothing and positions.  Unfortunately the DOF is too shallow to make it work; even a stop or two more detail in the foreground child would really make this one stand out. *6*', '2007-01-17 18:24:57.000000', NULL, 1),
