INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3248494, 453836, 70164, '<td valign="top">How many tries did this take?  wow.  Good shot though.  9</td>', 'How many tries did this take?  wow.  Good shot though.  9', '2007-01-17 18:32:35.000000', NULL, 1),
(3248496, 452926, 70164, '<td valign="top">Huh???</td>', 'Huh???', '2007-01-17 18:33:29.000000', NULL, 1),
(3248498, 454225, 70164, '<td valign="top">Perfect position of the sun.  But the backround looks fake.</td>', 'Perfect position of the sun.  But the backround looks fake.', '2007-01-17 18:34:23.000000', NULL, 1),
(3248499, 453089, 35086, '<td valign="top">Cool pattern.<br/>I''ve seen this concept before but not used in this fashion.  Pretty cool.</td>', 'Cool pattern.I''ve seen this concept before but not used in this fashion.  Pretty cool.', '2007-01-17 18:34:37.000000', NULL, 1),
(3248514, 453393, 35086, '<td valign="top">It''s almost hypnotic.</td>', 'It''s almost hypnotic.', '2007-01-17 18:36:13.000000', NULL, 1),
(3248516, 452610, 35086, '<td valign="top">The eye is drawn directly towards the light, almost hypnotizing.<br/> <br/>The centered composition works nice, helps to explore the entirety of the image, including the blured background which provides good contrast.</td>', 'The eye is drawn directly towards the light, almost hypnotizing. The centered composition works nice, helps to explore the entirety of the image, including the blured background which provides good contrast.', '2007-01-17 18:36:19.000000', NULL, 1),
(3248517, 454327, 35086, '<td valign="top">Cool concept, lovely light and effect.</td>', 'Cool concept, lovely light and effect.', '2007-01-17 18:36:24.000000', NULL, 1),
(3248518, 454300, 35086, '<td valign="top">Pretty neat idea, flipping the pic upside down.  <br/>Lovely reflections.</td>', 'Pretty neat idea, flipping the pic upside down.  Lovely reflections.', '2007-01-17 18:36:28.000000', NULL, 1),
(3248519, 454257, 70164, '<td valign="top">Whats the heart of it?</td>', 'Whats the heart of it?', '2007-01-17 18:36:30.000000', NULL, 1),
(3248520, 453336, 35086, '<td valign="top">Interesting shot, very eerie.</td>', 'Interesting shot, very eerie.', '2007-01-17 18:36:33.000000', NULL, 1),
(3248521, 454344, 35086, '<td valign="top">Interesting colours, love the details, cool idea.</td>', 'Interesting colours, love the details, cool idea.', '2007-01-17 18:36:38.000000', NULL, 1),
(3248523, 454347, 35086, '<td valign="top">Awesome concept, even before reading the title I could see the famous image reflected from this.  Well executed.</td>', 'Awesome concept, even before reading the title I could see the famous image reflected from this.  Well executed.', '2007-01-17 18:36:43.000000', NULL, 1),
(3248524, 453362, 35086, '<td valign="top">Not a very fair match but a match none the less.<br/>Funny stuff, toys are fun, makes me want to be a kid.</td>', 'Not a very fair match but a match none the less.Funny stuff, toys are fun, makes me want to be a kid.', '2007-01-17 18:36:47.000000', NULL, 1),
(3248525, 453195, 35086, '<td valign="top">The colours are really alluring, just as are the details.</td>', 'The colours are really alluring, just as are the details.', '2007-01-17 18:36:51.000000', NULL, 1),
(3248526, 452808, 35086, '<td valign="top">I''m usualy disconcerted by odd angles but this seems the right application of such a shot.  It works.</td>', 'I''m usualy disconcerted by odd angles but this seems the right application of such a shot.  It works.', '2007-01-17 18:37:00.000000', NULL, 1),
(3248527, 450925, 35086, '<td valign="top">Cuteness...</td>', 'Cuteness...', '2007-01-17 18:37:04.000000', NULL, 1),
(3248529, 451412, 35086, '<td valign="top">Very romantic.<br/>The backlit effect is ideal but I would have prefered more sky, perhaps a coastline at the bottom third or just a lower angle would have given this an extra kick.</td>', 'Very romantic.The backlit effect is ideal but I would have prefered more sky, perhaps a coastline at the bottom third or just a lower angle would have given this an extra kick.', '2007-01-17 18:37:15.000000', NULL, 1),
(3248530, 453488, 70164, '<td valign="top">Boring.</td>', 'Boring.', '2007-01-17 18:37:17.000000', NULL, 1),
(3248533, 451339, 35086, '<td valign="top">Isn''t fire fun?<br/>A little off center, which is too bad.  Else than that, I find it''s pretty neat and intersting.</td>', 'Isn''t fire fun?A little off center, which is too bad.  Else than that, I find it''s pretty neat and intersting.', '2007-01-17 18:37:23.000000', NULL, 1),
(3248535, 453723, 35086, '<td valign="top">I think this is something that most people can relate too.</td>', 'I think this is something that most people can relate too.', '2007-01-17 18:37:27.000000', NULL, 1),
(3248538, 454125, 35086, '<td valign="top">Nice timing, lovely blend of movement and color.</td>', 'Nice timing, lovely blend of movement and color.', '2007-01-17 18:39:02.000000', NULL, 1),
