(3262785, 452610, 42181, '<td valign="top">Good picture, i like the DOF and for a change i like the use of a frame. 8</td>', 'Good picture, i like the DOF and for a change i like the use of a frame. 8', '2007-01-21 16:42:55.000000', NULL, 1),
(3262814, 453985, 72577, '<td valign="top">Good rule of third horizontally.  I think you should have cropped the picture so the birds had more room to look to the left - this way it feels too crowded.  Beautiful muted colors in the background - it was a nice choice to have a shollow depth of field.</td>', 'Good rule of third horizontally.  I think you should have cropped the picture so the birds had more room to look to the left - this way it feels too crowded.  Beautiful muted colors in the background - it was a nice choice to have a shollow depth of field.', '2007-01-21 16:56:40.000000', NULL, 1),
