INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3264153, 453985, 30049, '<td valign="top">What a wonderful find.  Good eye to see this and do a nice job of getting the photo.  Interesting to look at as this pair is just different enough to keep the viewer entertained.  Nice job with the DOF to eliminate the background.  Good luck in the challenge.</td>', 'What a wonderful find.  Good eye to see this and do a nice job of getting the photo.  Interesting to look at as this pair is just different enough to keep the viewer entertained.  Nice job with the DOF to eliminate the background.  Good luck in the challenge.', '2007-01-21 23:08:46.000000', NULL, 1),
(3264157, 453605, 30049, '<td valign="top">I recently picked up a wilderness survival game built like this one, at an antique store.  I wonder how many will know what this is?  Interesting take on the challenge.  Good luck to you.</td>', 'I recently picked up a wilderness survival game built like this one, at an antique store.  I wonder how many will know what this is?  Interesting take on the challenge.  Good luck to you.', '2007-01-21 23:10:31.000000', NULL, 1),
(3264159, 454181, 30049, '<td valign="top">The processing is bit too much over the top for my taste.  Sorry.  Good luck in the challenge.</td>', 'The processing is bit too much over the top for my taste.  Sorry.  Good luck in the challenge.', '2007-01-21 23:11:13.000000', NULL, 1),
(3264166, 454162, 30049, '<td valign="top">Somebody has WAY too much time on their hands!  :D  Cute, clever, creative, borderline compulsive...  BTW, it''s legal now to remove sensor dust spots in the basic editing ruleset.  Good luck in the challenge.</td>', 'Somebody has WAY too much time on their hands!  :D  Cute, clever, creative, borderline compulsive...  BTW, it''s legal now to remove sensor dust spots in the basic editing ruleset.  Good luck in the challenge.', '2007-01-21 23:13:16.000000', NULL, 1),
(3264215, 454251, 44877, '<td valign="top">In my opinion, it would make for a better photo if the focus were sharp in front. Also, it would be awesome if one of the puzzle pieces were not completely in place. The colorse are great and the concept is good.</td>', 'In my opinion, it would make for a better photo if the focus were sharp in front. Also, it would be awesome if one of the puzzle pieces were not completely in place. The colorse are great and the concept is good.', '2007-01-21 23:28:49.000000', NULL, 1),
(3264220, 451301, 44877, '<td valign="top">The lighting is dull and reflection off of the cigarette package is distracting. But it''s a great idea!</td>', 'The lighting is dull and reflection off of the cigarette package is distracting. But it''s a great idea!', '2007-01-21 23:30:49.000000', NULL, 1),
(3264248, 452610, 16402, '<td valign="top">Something (lighting I think) very elegant about this image. Good Job. 8<br/> <br/>Since I had several 8s tying, I bumped you up as the "winner" with a 9.<br/> <br/>Great job!</td>', 'Something (lighting I think) very elegant about this image. Good Job. 8 Since I had several 8s tying, I bumped you up as the "winner" with a 9. Great job!', '2007-01-21 23:39:54.000000', NULL, 1),
