(3270527, 454333, 66952, '<td valign="top">Beautiful portrait. Nothing much else to say...</td>', 'Beautiful portrait. Nothing much else to say...', '2007-01-23 10:33:13.000000', NULL, 1),
(3270530, 453959, 66952, '<td valign="top">Great concept, well executed. One of my top 3.</td>', 'Great concept, well executed. One of my top 3.', '2007-01-23 10:33:43.000000', NULL, 1),
