(3270768, 451214, 30049, '<td valign="top">The metal shavings are a nice touch, as is the soft reflection.  Nicely done.</td>', 'The metal shavings are a nice touch, as is the soft reflection.  Nicely done.', '2007-01-23 12:34:34.000000', NULL, 1),
(3270771, 454324, 30049, '<td valign="top">But the box says Muncie, IN 47305.  :D  That''s what you get for having such a finely detailed, well focused image!  Cute.  Good luck.</td>', 'But the box says Muncie, IN 47305.  :D  That''s what you get for having such a finely detailed, well focused image!  Cute.  Good luck.', '2007-01-23 12:36:37.000000', NULL, 1),
