(3272308, 453130, 66952, '<td valign="top">Awwww, poor guy....get that woody some prozac!<br/> <br/>I really like the directional lighting, it does a good job of emphasizing woody''s depression (I can''t believe I just wrote that). But I''d change the direction a bit to bring up the light on the "rope" and matches. It took a sec for my eye to notice them, so I didn''t understand the title at first.</td>', 'Awwww, poor guy....get that woody some prozac! I really like the directional lighting, it does a good job of emphasizing woody''s depression (I can''t believe I just wrote that). But I''d change the direction a bit to bring up the light on the "rope" and matches. It took a sec for my eye to notice them, so I didn''t understand the title at first.', '2007-01-23 20:00:18.000000', NULL, 1),
(3272315, 452846, 66952, '<td valign="top">I like how the eye is drawn back from the kid to grandma. I really had to look to figure out what the ''match'' was, but it was worth my time. Nice job.</td>', 'I like how the eye is drawn back from the kid to grandma. I really had to look to figure out what the ''match'' was, but it was worth my time. Nice job.', '2007-01-23 20:01:46.000000', NULL, 1),
(3272317, 452610, 66952, '<td valign="top">Nice. Much more interesting than all of the <i>matches against black background</i> shots.</td>', 'Nice. Much more interesting than all of the matches against black background shots.', '2007-01-23 20:02:35.000000', NULL, 1),
(3272465, 453437, 31341, '<td valign="top">Man, I am trying, but I am missing the match part...</td>', 'Man, I am trying, but I am missing the match part...', '2007-01-23 20:50:41.000000', NULL, 1),
