INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3273027, 454099, 30049, '<td valign="top">I like the concept, the lighting is fair (could be a little brighter).  Thing holding this back some for me is it''s cluttered.  Too many pieces on the board.  You could have used 1/2 of those and gotten the message across a little stronger.  JMO of course.  :D  Good luck in the challenge.</td>', 'I like the concept, the lighting is fair (could be a little brighter).  Thing holding this back some for me is it''s cluttered.  Too many pieces on the board.  You could have used 1/2 of those and gotten the message across a little stronger.  JMO of course.  :D  Good luck in the challenge.', '2007-01-23 23:08:08.000000', NULL, 1),
